from collections import defaultdict
from fixtures.inventory import DEFAULT_STOCK


def solve(records):
    """Applies inventory deltas atomically and rejects invalid updates.

    Aggregates (sku, delta) from records. Rejects non-string SKUs and updates
    that would result in negative final stock (starting from DEFAULT_STOCK).
    Returns a sorted dictionary mapping SKU to final stock.
    """
    # Aggregate deltas per SKU
    deltas = defaultdict(int)
    for record in records:
        if not isinstance(record, (list, tuple)) or len(record) != 2:
            continue
        sku, delta = record
        if not isinstance(sku, str):
            continue
        if not isinstance(delta, (int, float)):
            try:
                delta = int(delta)
            except (ValueError, TypeError):
                continue
        deltas[sku] += delta

    # Compute final stock and validate against constraints atomically
    final_stock = {}
    for sku, initial in DEFAULT_STOCK.items():
        final_stock[sku] = initial + deltas[sku]

    # Include any new SKUs introduced in deltas not in DEFAULT_STOCK
    for sku, delta in deltas.items():
        if sku not in final_stock:
            final_stock[sku] = delta

    # Check for negative final stock
    for sku, stock in final_stock.items():
        if stock < 0:
            # Reject invalid update: return original DEFAULT_STOCK sorted by SKU
            return dict(sorted(DEFAULT_STOCK.items()))

    # Return sorted stock mapping
    return dict(sorted(final_stock.items()))
