class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        # Using a doubly linked list approach via a dictionary or Python 3.7+ ordered dict behavior.
        # Since standard dict maintains insertion order in Python 3.7+, we can use it directly.

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        # Move to end to show it was recently used
        self.cache[key] = self.cache.pop(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Remove existing so it gets updated and moved to the end
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            # Evict the least recently used item (the first item in the dict)
            oldest_key = next(iter(self.cache))
            self.cache.pop(oldest_key)

        self.cache[key] = value
