def solve(intervals):
    if not intervals:
        return []

    # Sort intervals by their starting value to avoid mutating the input
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        prev = merged[-1]
        # If current overlaps or touches the previous interval, merge them
        if current[0] <= prev[1]:
            merged[-1] = [prev[0], max(prev[1], current[1])]
        else:
            merged.append(current)

    return merged
